import { test, expect } from '@playwright/test';

test.describe('Multi-step form navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/multi-step-form');
  });

  test('should navigate back to previous step and retain data', async ({ page }) => {
    // Fill out first step
    await page.getByLabel('First Name').fill('John');
    await page.getByLabel('Last Name').fill('Doe');
    await page.getByLabel('Email').fill('john.doe@example.com');

    // Click next button to go to step 2
    await page.getByRole('button', { name: /next/i }).click();

    // Verify we're on step 2
    await expect(page.getByText('Step 2 of 3')).toBeVisible();

    // Fill out second step
    await page.getByLabel('Phone Number').fill('555-1234');
    await page.getByLabel('Address').fill('123 Main St');

    // Click back button
    await page.getByRole('button', { name: /back/i }).click();

    // Verify we're back on step 1
    await expect(page.getByText('Step 1 of 3')).toBeVisible();

    // Verify data is retained
    await expect(page.getByLabel('First Name')).toHaveValue('John');
    await expect(page.getByLabel('Last Name')).toHaveValue('Doe');
    await expect(page.getByLabel('Email')).toHaveValue('john.doe@example.com');
  });

  test('should navigate forward and backward multiple times preserving all data', async ({ page }) => {
    // Step 1: Fill personal information
    await page.getByLabel('First Name').fill('Jane');
    await page.getByLabel('Last Name').fill('Smith');
    await page.getByLabel('Email').fill('jane.smith@example.com');

    // Go to step 2
    await page.getByRole('button', { name: /next/i }).click();
    await expect(page.getByText('Step 2 of 3')).toBeVisible();

    // Step 2: Fill contact information
    await page.getByLabel('Phone Number').fill('555-5678');
    await page.getByLabel('Address').fill('456 Oak Ave');

    // Go to step 3
    await page.getByRole('button', { name: /next/i }).click();
    await expect(page.getByText('Step 3 of 3')).toBeVisible();

    // Step 3: Fill additional information
    await page.getByLabel('Company').fill('Tech Corp');
    await page.getByLabel('Job Title').fill('Engineer');

    // Go back to step 2
    await page.getByRole('button', { name: /back/i }).click();
    await expect(page.getByText('Step 2 of 3')).toBeVisible();

    // Verify step 2 data is retained
    await expect(page.getByLabel('Phone Number')).toHaveValue('555-5678');
    await expect(page.getByLabel('Address')).toHaveValue('456 Oak Ave');

    // Go back to step 1
    await page.getByRole('button', { name: /back/i }).click();
    await expect(page.getByText('Step 1 of 3')).toBeVisible();

    // Verify step 1 data is retained
    await expect(page.getByLabel('First Name')).toHaveValue('Jane');
    await expect(page.getByLabel('Last Name')).toHaveValue('Smith');
    await expect(page.getByLabel('Email')).toHaveValue('jane.smith@example.com');

    // Go forward to step 2 again
    await page.getByRole('button', { name: /next/i }).click();
    await expect(page.getByText('Step 2 of 3')).toBeVisible();

    // Verify step 2 data is still retained
    await expect(page.getByLabel('Phone Number')).toHaveValue('555-5678');
    await expect(page.getByLabel('Address')).toHaveValue('456 Oak Ave');

    // Go forward to step 3
    await page.getByRole('button', { name: /next/i }).click();
    await expect(page.getByText('Step 3 of 3')).toBeVisible();

    // Verify step 3 data is retained
    await expect(page.getByLabel('Company')).toHaveValue('Tech Corp');
    await expect(page.getByLabel('Job Title')).toHaveValue('Engineer');
  });

  test('should preserve form data when using step indicators to navigate', async ({ page }) => {
    // Fill step 1
    await page.getByLabel('First Name').fill('Bob');
    await page.getByLabel('Last Name').fill('Johnson');
    await page.getByLabel('Email').fill('bob.johnson@example.com');

    // Click next to go to step 2
    await page.getByRole('button', { name: /next/i }).click();

    // Fill step 2
    await page.getByLabel('Phone Number').fill('555-9999');
    await page.getByLabel('Address').fill('789 Pine Rd');

    // Click on step 1 indicator to go back
    await page.getByRole('button', { name: /step 1/i }).click();

    // Verify we're on step 1 and data is preserved
    await expect(page.getByText('Step 1 of 3')).toBeVisible();
    await expect(page.getByLabel('First Name')).toHaveValue('Bob');
    await expect(page.getByLabel('Last Name')).toHaveValue('Johnson');
    await expect(page.getByLabel('Email')).toHaveValue('bob.johnson@example.com');

    // Click on step 2 indicator to go forward
    await page.getByRole('button', { name: /step 2/i }).click();

    // Verify we're on step 2 and data is preserved
    await expect(page.getByText('Step 2 of 3')).toBeVisible();
    await expect(page.getByLabel('Phone Number')).toHaveValue('555-9999');
    await expect(page.getByLabel('Address')).toHaveValue('789 Pine Rd');
  });
});
